def write(name,x): (D/name).write_text(json.dumps(x,sort_keys=True,indent=2,default=lambda v:dict(v) if hasattr(v,'items') else list(v) if isinstance(v,tuple) else str(v))+"\n")
def main():
 root=core.materialize(); p=core.IFermContactSupportPackage(); v=core.validate_package(); records={r.label:p.load_iferm_contact_support_package(r.label) for r in core.RESOLUTIONS}
